// Cuts the Tabler icon font (5,000+ icons, about 500 KB) down to the icons the app really uses (about 20 KB).
// Run it whenever an icon is added or removed:   npm run icons:build
// It needs Python with fonttools and brotli:       python3 -m pip install fonttools brotli
// (set PYTHON=/path/to/python if those are installed somewhere else). The generated files are committed, so deploys do not need Python.
import { readFileSync, writeFileSync, readdirSync, statSync, mkdtempSync } from 'node:fs'
import { join, extname, resolve } from 'node:path'
import { tmpdir } from 'node:os'
import { spawnSync } from 'node:child_process'
import { mergeScans, neededIcons, parseTablerCss, scanSource } from './lib/iconScan.mjs'

const ROOT = resolve(import.meta.dirname, '..')
const TABLER = join(ROOT, 'node_modules/@tabler/icons-webfont/dist')
const OUT_CSS = join(ROOT, 'src/app/tabler-icons-subset.css')
const OUT_FONT = join(ROOT, 'src/app/tabler-icons-subset.woff2')

function walk(dir, out = []) {
  for (const f of readdirSync(dir)) {
    const p = join(dir, f)
    if (statSync(p).isDirectory()) walk(p, out)
    else if (['.ts', '.tsx', '.js', '.jsx', '.mjs', '.css'].includes(extname(p)) && p !== OUT_CSS) out.push(p)
  }
  return out
}

const scan = mergeScans(walk(join(ROOT, 'src')).map((f) => scanSource(readFileSync(f, 'utf8'))))
if (scan.bare.length) { console.error('Cannot cut the font: an icon name is built from nothing fixed ("ti-${...}"). Give it a fixed start, e.g. ti-arrow-${dir}.'); process.exit(1) }

const css = readFileSync(join(TABLER, 'tabler-icons.css'), 'utf8')
const known = parseTablerCss(css)
const { need, notIcons, emptyPrefixes } = neededIcons(scan, known)
if (emptyPrefixes.length) { console.error('These built icon names match no icon:', emptyPrefixes.join(', ')); process.exit(1) }
if (notIcons.length) console.warn('Ignored (not Tabler icons):', notIcons.join(', '))

const dir = mkdtempSync(join(tmpdir(), 'icons-'))
const cpFile = join(dir, 'codepoints.txt')
writeFileSync(cpFile, need.map((n) => known.get(n)).join('\n'))
const py = process.env.PYTHON || 'python3'
const run = spawnSync(py, [join(ROOT, 'scripts/subset-font.py'), join(TABLER, 'fonts/tabler-icons.ttf'), cpFile, OUT_FONT], { stdio: 'inherit' })
if (run.status !== 0) { console.error('The font could not be cut. Is fonttools installed?  python3 -m pip install fonttools brotli'); process.exit(1) }

const header = `/* GENERATED by scripts/build-icon-font.mjs. Do not edit by hand: run  npm run icons:build  after adding or removing an icon.
 * Tabler Icons ${/Tabler Icons ([0-9.]+)/.exec(css)?.[1] ?? ''} (MIT, https://tabler.io), cut down to the ${need.length} icons this app uses.
 * The full font is about 500 KB; this one is a few KB, which matters on slow or paid-for connections. */
`
const base = `@font-face {
  font-family: "tabler-icons";
  font-style: normal;
  font-weight: 400;
  font-display: block;
  src: url("./tabler-icons-subset.woff2") format("woff2");
}
.ti {
  font-family: "tabler-icons" !important;
  speak: none;
  font-style: normal;
  font-weight: normal;
  font-variant: normal;
  text-transform: none;
  line-height: 1;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
`
const rules = need.map((n) => `.${n}:before { content: "\\${known.get(n).toString(16)}"; }`).join('\n')
writeFileSync(OUT_CSS, header + base + rules + '\n')
console.log(`Wrote ${OUT_CSS} and ${OUT_FONT} (${need.length} icons, font ${(statSync(OUT_FONT).size / 1024).toFixed(1)} KB)`)
